package com.ddagtech.aureliabooks.dto.request;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.util.Locale;

/**
 * Request DTO for provisioning internal staff accounts (UC28 / FE-1).
 * Enforces field validations including email structure, display name,
 * and Vietnamese 10-digit mobile phone number format (BR-07-01).
 * Initial password is cryptographically auto-generated by the system
 * and delivered via email to satisfy non-repudiation.
 *
 * @param email user login and contact email address
 * @param fullName user full display name
 * @param phone mobile phone number following Vietnamese telecom format (BR-07-01)
 * @param roleId persistent role identifier to be assigned
 */
public record UserCreateRequest(
        @NotBlank(message = "Email không được để trống")
        @Email(message = "Định dạng email không hợp lệ")
        @Size(max = 100, message = "Email tối đa 100 ký tự")
        String email,

        @NotBlank(message = "Họ và tên không được để trống")
        @Size(max = 100, message = "Họ và tên tối đa 100 ký tự")
        String fullName,

        @NotBlank(message = "Số điện thoại không được để trống")
        @Pattern(regexp = "^(0|\\+84)[35789][0-9]{8}$", message = "Số điện thoại không đúng định dạng Việt Nam (10 chữ số)")
        String phone,

        @NotNull(message = "Vui lòng chọn vai trò nhân viên")
        Long roleId
) {
    public UserCreateRequest {
        email = email != null ? email.strip().toLowerCase(Locale.ROOT) : null;
        fullName = fullName != null ? fullName.strip() : null;
        if (phone != null) {
            String cleaned = phone.strip().replace(" ", "").replace("-", "");
            if (cleaned.startsWith("+84") && cleaned.length() == 12) {
                cleaned = "0" + cleaned.substring(3);
            } else if (cleaned.startsWith("84") && cleaned.length() == 11) {
                cleaned = "0" + cleaned.substring(2);
            }
            phone = cleaned;
        }
    }

    /**
     * Backward-compatible constructor accepting legacy password parameter.
     * Note: Initial password is now automatically generated on creation to uphold non-repudiation.
     */
    public UserCreateRequest(String email, String password, String fullName, String phone, Long roleId) {
        this(email, fullName, phone, roleId);
    }

    /**
     * Backward-compatible accessor returning null.
     */
    @Deprecated
    public String password() {
        return null;
    }

    @Override
    @SuppressWarnings("NullableProblems")
    public String toString() {
        return "UserCreateRequest[email=" + email + ", fullName=" + fullName + ", phone=" + phone + ", roleId=" + roleId + "]";
    }
}
